// MPLPB local patch: retain supported intermediate capacities.
const requiredMaxBufferSize = Math.min(1 << 30, adapter.limits.maxBufferSize);
const requiredMaxStorageBufferBindingSize = Math.min(1 << 30, adapter.limits.maxStorageBufferBindingSize);

// MPLPB local patch: check the negotiated device, not only its adapter.
function mplpbValidateDeviceLimits(record, device) {
    const limits = {
        maxBufferSize: device.limits.maxBufferSize,
        maxStorageBufferBindingSize: device.limits.maxStorageBufferBindingSize,
    };
    const minimum = record.mplpb_minimum_tensor_buffer_bytes;
    if (minimum !== undefined && (!Number.isSafeInteger(minimum) || minimum <= 0 ||
        !Number.isFinite(limits.maxBufferSize) || !Number.isFinite(limits.maxStorageBufferBindingSize) ||
        limits.maxBufferSize < minimum || limits.maxStorageBufferBindingSize < minimum)) {
        throw new Error(`Negotiated GPU device cannot hold the model tensor: required=${minimum} bytes; ` +
            `maxBufferSize=${limits.maxBufferSize}; maxStorageBufferBindingSize=${limits.maxStorageBufferBindingSize}.`);
    }
    return limits;
}
